    # build adjacency list for the directed graph
    adj = {}
    for a, b in edges:
        adj.setdefault(a, []).append(b)

    # BFS to find the shortest path length in edges
    visited = {source}
    queue = deque([(source, 0)])   # (node, distance from source)

